mapper.select:
select kd.id, kd.question, kd.answer, c.name as categoryName, kd.source, CASE kd.status WHEN 0 THEN '待审核' WHEN 1 THEN '已通过' END as statusDesc, kd.status, kd.created_time as createdTime, kd.reviewed_time as reviewedTime from knowledge_draft kd left join category c on kd.category_id = c.id
and kd.status = #{status}
and kd.category_id = #{categoryId}
and kd.question like concat('%', #{keyword}, '%')
and kd.created_time >= #{startTime}
and kd.created_time <= #{endTime}
order by kd.created_time
desc
asc

select count(*)
from knowledge_draft
where status = #{status}

select count(*)
from knowledge_draft
where created_time >= #{time}

select count(*)
from knowledge_draft
where created_time >= #{start} and created_time < #{end}

select count(*)
from knowledge_draft
where status = 1 and reviewed_time >= #{time}

select count(*)
from knowledge_draft
where status = 1 and reviewed_time >= #{start} and reviewed_time < #{end}
